// Auto-declarations to satisfy Next.js generated type imports like "../../app/page.js"
// These declarations treat app route modules as `any` to avoid TypeScript errors

declare module "../../app/*" {
  const Component: any;
  export default Component;
}

declare module "../../app/*/*" {
  const Component: any;
  export default Component;
}

declare module "../../app/*/*/*" {
  const Component: any;
  export default Component;
}

declare module "../../app/*/*/*/*" {
  const Component: any;
  export default Component;
}

declare module "../../app/*/*/*/*/*" {
  const Component: any;
  export default Component;
}
